import ast
import sys
from pathlib import Path

errors = []
for py_file in Path('.').rglob('*.py'):
    try:
        with open(py_file, 'r') as f:
            ast.parse(f.read())
    except SyntaxError as e:
        errors.append(f'{py_file}: {e}')

if errors:
    print('语法错误:')
    for err in errors:
        print(f'  {err}')
    sys.exit(1)
else:
    print('✓ 所有 Python 文件语法检查通过')
